func IslandStopped(name string) string { return In(i18n.Locale()).IslandStopped(name) }

// IslandStopped says "{name} stopped"
// in the language of msgs.
func (msgs Messages) IslandStopped(name string) string {
	return Catalog.Format(msgs.locale, "islandStopped", map[string]any{"name": name})
}

